sys_script_include.script:
var FitnessUtils = Class.create();
FitnessUtils.prototype = {
    initialize: function() {
    },

    /**
     * Calculate XP earned based on activity type and duration
     * @param {string} activityType - Type of activity (pushup, run, etc)
     * @param {number} count - Number of reps or duration
     * @return {number} XP earned
     */
    calculateXP: function(activityType, count) {
        var xpMultipliers = {
            'pushup': 1,
            'pullup': 2,
            'run': 0.5,
            'plank': 0.3
        };

        var multiplier = xpMultipliers[activityType] || 1;
        return Math.floor(count * multiplier);
    },

    /**
     * Check if user has achieved a new streak milestone
     * @param {number} currentStreak - Current streak count
     * @return {boolean} Whether a milestone was achieved
     */
    checkStreakMilestone: function(currentStreak) {
        var milestones = [7, 14, 30, 60, 90, 180, 365];
        return milestones.indexOf(currentStreak) > -1;
    },

    type: 'FitnessUtils'
};
